root<-commandArgs(trailingOnly=TRUE)[1];p<-file.path(root,'results');d<-read.csv(file.path(p,'primary-longitudinal.csv'));years<-sort(unique(d$period));getv<-function(metric){s<-d[d$metric==metric,];s$value[match(years,s$period)]}
render<-function(){par(family='Times New Roman',mfrow=c(2,1),mar=c(3.2,4.2,2,1),oma=c(1,0,1,0));stock<-getv('cases_on_hand_30_June');plot(1:11,stock,pch=21,bg='#467C90',type='o',col='#467C90',axes=FALSE,xlab='',ylab='Cases on hand');axis(1,at=1:11,labels=years,cex.axis=.65);axis(2,las=1,cex.axis=.8);title('A  Outstanding workload rose, then fell',adj=0,cex.main=.95);text(c(1,9,11),stock[c(1,9,11)],labels=format(stock[c(1,9,11)],big.mark=','),pos=c(3,1,3),cex=.8,col='black');m<-getv('mean_days_case_closure');plot(1:11,m,pch=21,bg=ifelse(1:11>=7,'#467C90','#BE946B'),axes=FALSE,xlab='',ylab='Mean days to closure',ylim=c(250,690));abline(h=365,lty=2,col='#767676');axis(1,at=1:11,labels=years,cex.axis=.65);axis(2,las=1,cex.axis=.8);text(2,380,'One year',cex=.7);text(1:11,m,labels=m,pos=3,cex=.75);abline(v=6.5,lty=3,col='#A0A0A0');title('B  Recent annual means consistently exceeded one year',adj=0,cex.main=.95);mtext('Latest retained edition per year; earlier definitions differ. Alternative editions retained in sensitivity analysis.',side=1,line=1.7,cex=.62);mtext('New Zealand coronial workload and completion time',outer=TRUE,line=-.1,adj=0,cex=1.0,font=2)}
png(file.path(p,'figure1.png'),width=2100,height=1800,res=300,type='cairo');render();dev.off();cairo_pdf(file.path(p,'figure1.pdf'),width=7,height=6,family='Times New Roman');render();dev.off();svg(file.path(p,'figure1.svg'),width=7,height=6);render();dev.off()
